import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry (default 1x1, will scale via scenePosition)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the feature card texture
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create plane mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position
  if (config.scenePosition) {
    mesh.position.copy(config.scenePosition);
  }

  // Apply rotation if specified
  if (config.rotation) {
    mesh.rotation.order = 'YXZ';
    mesh.rotation.x = config.rotation[0] ?? 0;
    mesh.rotation.y = config.rotation[1] ?? 0;
    mesh.rotation.z = config.rotation[2] ?? 0;
  }

  // Apply scale if specified
  if (config.scale) {
    mesh.scale.copy(config.scale);
  }

  // Load and apply texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;
      material.colorNode = texture;
      material.needsUpdate = true;
    });
  }

  // Set up cleanup
  mesh.userData.cleanup = function cleanup() {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
